import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { addItem, removeItem } from './cartSlice';

const CartComponent = props => {
  const cart = useSelector(state => state.cart);
  const dispatch = useDispatch();

  return (
    <div class="cart">
      <h2>cart</h2>
      {cart.items.map(item => {
        return (
          <div key={item.id}>
            {item.name} <button onClick={() => dispatch(removeItem(item.id))}>x</button>
          </div>
        );
      })}
      <button onClick={() => dispatch(addItem(props.product))}>add to cart</button>
    </div>
  );
};

export default CartComponent;
```

Components in React are just functions, so here's a quick example:

```jsx
import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { selectCart } from './cartSlice';
import { addItem, removeItem } from './cartSlice';
import ShoppingCartIcon from '@material-ui/icons/ShoppingCart';
import { Button } from '@material-ui/core';

const CartComponent = () => {
  const cart = useSelector(selectCart);
  const dispatch = useDispatch();

  return (
    <div className="cart">
      <h3> Shopping Cart {cart.items.length}</h3>
      <div className="cart__items">
        {cart.items.map(item => {
          return (
            <div key={item.id}>
              <h3>{item.name}</h3>
              <button onClick={() => dispatch(removeItem(item.id))}>
                Remove
              </button>
              <QuantityInput quantity={item.quantity} />
            </div>);
        })}
      </div>
      <div className="cart__buttons">
        <Button variant="contained" color="primary">
          Checkout
        </Button>
        <Button variant="contained" color="primary">
          Continue Shopping
        </Button>
      </div>
    </div>
  );
};

const QuantityInput = (props) => {
  return (
    <div className="cart__quantity">
      <Button onClick={() => props.quantity > 1 && props.quantity--}>
        -
      </Button>
      <Button onClick={() => props.quantity += 1}>{props.quantity}</Button>
      <Button onClick={() => props.quantity--}>+</Button>
    </div>
  );
};

export default CartComponent;
```

This is super basic, but hopefully it gets you started. This is an actual implementation, so adjust the CSS to fit your needs.

